pub(super) fn names(locale: &str) -> (&'static [&'static str], &'static [&'static str]) {
    match locale {
        "ar_EG" => (SAFE_AR_EG, ALL_AR_EG),
        "ar_SA" => (SAFE_AR_SA, ALL_AR_SA),
        "es_ES" => (SAFE_ES_ES, ALL_DEFAULT),
        "fr_BE" | "fr_CA" | "fr_CH" | "fr_FR" => (SAFE_FR_BE, ALL_FR_BE),
        "hy_AM" => (SAFE_HY_AM, ALL_DEFAULT),
        "id_ID" => (SAFE_ID_ID, ALL_ID_ID),
        "ka_GE" => (SAFE_KA_GE, SAFE_KA_GE),
        "kk_KZ" => (SAFE_KK_KZ, ALL_DEFAULT),
        "lv_LV" => (SAFE_LV_LV, ALL_LV_LV),
        "nl_NL" => (SAFE_NL_NL, ALL_NL_NL),
        "pl_PL" => (SAFE_PL_PL, ALL_PL_PL),
        "ru_RU" => (SAFE_RU_RU, ALL_RU_RU),
        "th_TH" => (SAFE_TH_TH, ALL_TH_TH),
        "tr_TR" => (SAFE_TR_TR, ALL_TR_TR),
        "uk_UA" => (SAFE_UK_UA, ALL_UK_UA),
        "vi_VN" => (SAFE_VI_VN, ALL_VI_VN),
        "zh_CN" => (SAFE_ZH_CN, ALL_ZH_CN),
        "zh_TW" => (SAFE_ZH_TW, ALL_ZH_TW),
        _ => (SAFE_DEFAULT, ALL_DEFAULT),
    }
}
